const { chromium } = require("<HOME>/AppData/Local/npm-cache/_npx/13ab0715f9f30c2e/node_modules/playwright");

const url = "file:///<WORKSPACE>/landing/index.html";
const widths = [320, 360, 390, 520, 640, 768, 940, 941, 1024, 1080, 1280, 1440, 1920];

(async () => {
  const browser = await chromium.launch();
  for (const width of widths) {
    const page = await browser.newPage({ viewport: { width, height: 900 } });
    const errors = [];
    page.on("console", (msg) => {
      if (msg.type() === "error") errors.push(msg.text());
    });
    await page.goto(url, { waitUntil: "load" });
    await page.evaluate(() => document.fonts.ready);
    const data = await page.evaluate(() => {
      const over = [];
      for (const el of document.querySelectorAll("body *")) {
        const cs = getComputedStyle(el);
        if (el.clientWidth > 0 && el.scrollWidth > el.clientWidth + 2 && cs.overflowX === "visible") {
          over.push({
            tag: el.tagName,
            cls: typeof el.className === "string" ? el.className : el.className.baseVal,
            sw: el.scrollWidth,
            cw: el.clientWidth,
          });
        }
      }
      const links = [...document.querySelectorAll("a")].map((a) => ({
        text: a.textContent.trim().replace(/\s+/g, " ").slice(0, 60),
        href: a.getAttribute("href"),
        target: a.getAttribute("target"),
      }));
      return {
        iw: innerWidth,
        sw: document.documentElement.scrollWidth,
        sh: document.documentElement.scrollHeight,
        heroH: Math.round(document.querySelector(".hero").getBoundingClientRect().height),
        h1: Math.round(document.querySelector("h1").getBoundingClientRect().width),
        nav: getComputedStyle(document.querySelector(".site-nav")).display,
        over: over.slice(0, 12),
        links,
      };
    });
    const badLinks = data.links.filter((l) => l.href && l.href.includes("wikipedia") && l.href !== "https://en.wikipedia.org/wiki/Composition_with_Red,_Blue_and_Yellow");
    console.log(JSON.stringify({ width, ...data, links: undefined, badLinks, errors }));
    await page.close();
  }
  await browser.close();
})();


